/* card_render_probe - rikkaST render / message-lifecycle probe (task-4) */
(function () {
  'use strict';

  var TAG = '[CARD] card_render_probe';
  var MARKER = 'CARD_RENDER_PROBE_REGEX_APPLIED';
  var PLACEHOLDER = '[[CARD_RENDER_PROBE_REGEX_SLOT]]';
  var PROBE_REGEX_NAME = 'card_render_probe_regex';
  var PROBE_BOOK = 'card render probe book with spaces';
  var EVENT_WANT = {
    MESSAGE_UPDATED: 'message_updated',
    MESSAGE_SWIPED: 'message_swiped',
    MESSAGE_EDITED: 'message_edited',
    MESSAGE_DELETED: 'message_deleted'
  };

  function errName(e) {
    try { return String(((e && (e.name || 'Error')) || 'Error') + ': ' + ((e && e.message) || e)); }
    catch (_) { return 'unknown-error'; }
  }
  function json(v) {
    try { var s = JSON.stringify(v); return s === undefined ? String(v) : s; }
    catch (_) { return String(v); }
  }
  function emit(level, text) {
    var t = String(text);
    try { if (window.parent && typeof window.parent.__rikkaLog === 'function') window.parent.__rikkaLog(level, t); } catch (_) {}
    try { console.log(t); } catch (_) {}
  }
  function check(name, pass, detail) {
    emit(pass ? 'info' : 'warn', TAG + ' ' + name + ' ' + (pass ? 'PASS' : 'FAIL') + ' ' + (detail == null ? '' : String(detail)));
    return !!pass;
  }
  function api(name) {
    try { if (typeof window[name] === 'function') return window[name]; } catch (_) {}
    try { if (window.TavernHelper && typeof window.TavernHelper[name] === 'function') return window.TavernHelper[name]; } catch (_) {}
    return null;
  }
  function getCtx() {
    try { if (window.SillyTavern && typeof window.SillyTavern.getContext === 'function') return window.SillyTavern.getContext(); } catch (_) {}
    return null;
  }
  function tavernEvents() {
    try { if (window.TavernHelper && window.TavernHelper.tavern_events) return window.TavernHelper.tavern_events; } catch (_) {}
    try { if (window.tavern_events) return window.tavern_events; } catch (_) {}
    return null;
  }

  try {
    var msgs = null;
    var te = tavernEvents();

    /* ---------------- 1. window.parent / window.top ---------------- */
    var parentOk = false, parentIsIframe = false, parentLogOk = false, parentErr = null;
    try {
      parentOk = !!(window.parent);
      parentIsIframe = (window.parent !== window);
      parentLogOk = !!(window.parent && typeof window.parent.__rikkaLog === 'function');
    } catch (e) { parentErr = errName(e); }
    check('window_parent_reachable', parentOk && parentLogOk,
      'parent=' + parentOk + ' parentIsIframe=' + parentIsIframe + ' parentHasRikkaLog=' + parentLogOk + (parentErr ? ' err=' + parentErr : ''));

    var topOk = false, topErr = null, topSameAsParent = 'n/a';
    try { topOk = !!(window.top); } catch (e) { topErr = errName(e); }
    try { topSameAsParent = (window.top === window.parent); } catch (e) { topSameAsParent = 'ERR:' + errName(e); }
    check('window_top_reachable', topOk, 'top=' + topOk + ' top===parent=' + topSameAsParent + (topErr ? ' err=' + topErr : ''));

    var topStOk = false, topStErr = null, topStDetail = '';
    try {
      var tw = window.top;
      topStOk = !!(tw && tw.SillyTavern && typeof tw.SillyTavern.getContext === 'function');
      topStDetail = 'top.SillyTavern=' + (tw ? typeof tw.SillyTavern : 'null') + ' getContext=' + (tw && tw.SillyTavern ? typeof tw.SillyTavern.getContext : 'null');
    } catch (e) { topStErr = errName(e); }
    check('window_top_sillytavern', topStOk, topStDetail + (topStErr ? ' err=' + topStErr : ''));

    /* ---------------- 2. TavernHelper.getChatMessages ---------------- */
    var noArg = 'n/a';
    try {
      var gcm0 = api('getChatMessages');
      var r0 = gcm0 ? gcm0() : null;
      if (Array.isArray(r0)) { msgs = r0; noArg = 'array(len=' + r0.length + ')'; }
      else { noArg = 'non-array:' + (typeof r0); }
    } catch (e) { noArg = 'throw:' + errName(e); }

    var chatLen = -1;
    try { var c0 = getCtx(); chatLen = (c0 && Array.isArray(c0.chat)) ? c0.chat.length : -1; } catch (_) {}
    var resolvePath = 'noarg';
    if (!Array.isArray(msgs)) {
      try {
        var gcm1 = api('getChatMessages');
        var hi = chatLen > 0 ? chatLen - 1 : 0;
        var r1 = gcm1 ? gcm1('0-' + hi) : null;
        if (Array.isArray(r1)) { msgs = r1; resolvePath = 'range(0-' + hi + ')'; }
        else { resolvePath = 'range-failed'; }
      } catch (e2) { noArg += ' fallbackThrow:' + errName(e2); }
    }
    check('getchatmessages_array', Array.isArray(msgs),
      'isArray=' + Array.isArray(msgs) + ' count=' + (Array.isArray(msgs) ? msgs.length : 'null') +
      ' ctx.chat.length=' + chatLen + ' noarg=' + noArg + ' path=' + resolvePath);

    var lastRole = null, lastIsUser = null, lastMid = null;
    try {
      if (Array.isArray(msgs) && msgs.length > 0) {
        var last = msgs[msgs.length - 1];
        lastRole = last ? String(last.role) : null;
        lastIsUser = last ? !!last.is_user : null;
        lastMid = last ? last.message_id : null;
      }
    } catch (e) { lastRole = 'ERR:' + errName(e); }
    var roleOk = (lastRole === 'user' || lastRole === 'assistant' || lastRole === 'system' || lastRole === 'unknown');
    check('getchatmessages_last_role', roleOk,
      'count=' + (Array.isArray(msgs) ? msgs.length : 'null') + ' last_role=' + json(lastRole) +
      ' last_is_user=' + json(lastIsUser) + ' last_message_id=' + json(lastMid));

    /* ---------------- 3. 事件常量 + eventOn 监听 ---------------- */
    var missing = [], wrong = [];
    Object.keys(EVENT_WANT).forEach(function (k) {
      if (!te || te[k] === undefined) missing.push(k);
      else if (te[k] !== EVENT_WANT[k]) wrong.push(k + '=' + te[k]);
    });
    check('tavern_events_constants', !!te && missing.length === 0 && wrong.length === 0,
      'tavern_events=' + (te ? 'object' : 'null') + ' missing=' + json(missing) + ' wrong=' + json(wrong));

    var received = {};
    var registered = {};
    function makeHandler(name) {
      return function () {
        var args = Array.prototype.slice.call(arguments);
        received[name] = (received[name] || 0) + 1;
        emit('info', TAG + ' event_received name=' + name + ' args=' + json(args));
      };
    }
    Object.keys(EVENT_WANT).forEach(function (k) {
      var eon = api('eventOn');
      if (!eon) { registered[k] = 'ERR:no-eventOn'; return; }
      var name = (te && te[k]) || EVENT_WANT[k];
      try { eon(name, makeHandler(name)); registered[k] = 'ok'; }
      catch (e) { registered[k] = 'ERR:' + errName(e); }
    });
    var regOk = Object.keys(EVENT_WANT).every(function (k) { return registered[k] === 'ok'; });
    check('event_listeners_registered', regOk, json(registered));

    /* ---------------- 4. 世界书只读（名字带空格容错） ---------------- */
    var wbNames = null, wbErr = null;
    try { var f1 = api('getWorldbookNames'); wbNames = f1 ? f1() : null; } catch (e) { wbErr = errName(e); }
    check('worldbook_names_array', Array.isArray(wbNames),
      'isArray=' + Array.isArray(wbNames) + ' names=' + json(wbNames) + (wbErr ? ' err=' + wbErr : ''));

    var cw = null, cwErr = null, cwShapeOk = false, cwDetail = '';
    try { var f2 = api('getCharWorldbookNames'); cw = f2 ? f2() : null; } catch (e) { cwErr = errName(e); }
    try {
      cwShapeOk = !!cw && typeof cw === 'object' && !Array.isArray(cw) && ('primary' in cw) && Array.isArray(cw.additional);
      cwDetail = 'primary=' + json(cw && cw.primary) + ' additional=' + json(cw && cw.additional);
    } catch (e) { cwDetail = 'err=' + errName(e); }
    check('char_worldbook_names_shape', cwShapeOk,
      cwDetail + ' note=contract-is-{primary,additional[]}-not-array' + (cwErr ? ' err=' + cwErr : ''));

    var spaceOk = false, spaceDetail = '';
    try {
      var n1 = Array.isArray(wbNames) ? wbNames : [];
      var spaced = n1.filter(function (n) { return typeof n === 'string' && n.indexOf(' ') >= 0; });
      var primarySpaced = !!(cw && typeof cw.primary === 'string' && cw.primary.indexOf(' ') >= 0);
      var byName = null, byNameErr = null;
      try { var f3 = api('getCharWorldbookNames'); byName = f3 ? f3(PROBE_BOOK) : null; }
      catch (e) { byNameErr = errName(e); }
      spaceOk = spaced.length > 0 && primarySpaced;
      spaceDetail = 'spaced_names=' + json(spaced) + ' primary_spaced=' + primarySpaced +
        ' lookup_by_book_name=' + (byNameErr ? 'throw(documented):' + byNameErr : json(byName));
    } catch (e) { spaceDetail = 'err=' + errName(e); }
    check('worldbook_space_name_tolerated', spaceOk, spaceDetail);

    /* ---------------- 5. 正则脚本被宿主识别 ---------------- */
    var ext = null, rs = null, rsErr = null;
    try {
      var c = getCtx();
      var chars = c && c.characters;
      ext = (chars && chars[0] && chars[0].data && chars[0].data.extensions) || null;
      rs = ext ? ext.regex_scripts : null;
    } catch (e) { rsErr = errName(e); }
    var rsArr = Array.isArray(rs);
    var rsNames = [], foundScript = null;
    if (rsArr) {
      rs.forEach(function (x) {
        if (x && x.scriptName) rsNames.push(String(x.scriptName));
        if (x && x.scriptName === PROBE_REGEX_NAME) foundScript = x;
      });
    }
    check('regex_scripts_recognized', rsArr && !!foundScript,
      'isArray=' + rsArr + ' count=' + (rsArr ? rs.length : 'null') + ' names=' + json(rsNames) +
      ' probe_found=' + !!foundScript + (rsErr ? ' err=' + rsErr : ''));

    var fr = foundScript ? String(foundScript.findRegex || '') : '';
    var compiledOk = false, compDetail = '';
    try {
      var mm = fr.match(/^\/([\s\S]*)\/([a-zA-Z]*)$/);
      var src = mm ? mm[1] : fr;
      var flags = mm ? mm[2] : '';
      var re = new RegExp(src, flags);
      compiledOk = re.test(PLACEHOLDER);
      compDetail = 'findRegex=' + json(fr) + ' compiled=' + compiledOk + ' matches_placeholder=' + compiledOk;
    } catch (e) { compDetail = 'findRegex=' + json(fr) + ' compile_err=' + errName(e); }
    check('regex_pattern_compiles', compiledOk, compDetail);

    var scanned = 0, hasMarker = false, hasPlaceholder = false;
    try {
      if (Array.isArray(msgs)) {
        msgs.forEach(function (m) {
          var t = (m && typeof m.message === 'string') ? m.message : '';
          if (t) scanned++;
          if (t.indexOf(MARKER) >= 0) hasMarker = true;
          if (t.indexOf(PLACEHOLDER) >= 0) hasPlaceholder = true;
        });
      }
    } catch (_) {}
    check('regex_marker_in_stored_chat', hasMarker,
      'marker=' + hasMarker + ' raw_placeholder_present=' + hasPlaceholder + ' scanned=' + scanned +
      ' note=rikkaST-applies-card-regex-at-display-only,stored-chat-keeps-raw-first_mes');

    /* ---------------- 6. $(ready)+500ms 重建后二次断言 ---------------- */
    var jqOk = false;
    try { jqOk = (typeof window.$ === 'function' || typeof window.jQuery === 'function'); } catch (_) {}
    check('jquery_available', jqOk, '$=' + (typeof window.$) + ' jQuery=' + (typeof window.jQuery));

    function phase2(reason) {
      var pOk = false, pErr = null, pLog = false;
      try {
        pOk = !!(window.parent);
        pLog = !!(window.parent && typeof window.parent.__rikkaLog === 'function');
      } catch (e) { pErr = errName(e); }
      check('rerender_parent_reachable', pOk && pLog,
        'trigger=' + reason + ' parent=' + pOk + ' parentHasRikkaLog=' + pLog + (pErr ? ' err=' + pErr : ''));

      var tOk = false, tErr = null;
      try { tOk = !!(window.top && window.top.SillyTavern); } catch (e) { tErr = errName(e); }
      check('rerender_top_sillytavern', tOk, 'trigger=' + reason + ' top.SillyTavern=' + tOk + (tErr ? ' err=' + tErr : ''));

      var eon2 = api('eventOn');
      check('rerender_eventon_function', typeof eon2 === 'function',
        'trigger=' + reason + ' typeof(eventOn)=' + (typeof eon2));
    }

    try {
      var jq = window.$ || window.jQuery;
      if (typeof jq === 'function') {
        jq(function () { setTimeout(function () { phase2('$(ready)+500ms'); }, 500); });
      } else {
        setTimeout(function () { phase2('no-jquery+500ms'); }, 500);
      }
    } catch (e) {
      check('rerender_schedule', false, 'err=' + errName(e));
      setTimeout(function () { phase2('schedule-error+500ms'); }, 500);
    }
  } catch (e) {
    emit('error', TAG + ' probe_bootstrap_error FAIL ' + errName(e));
  }
})();
